package net.officefloor.hq.app.audit;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.util.List;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/** The audit lines of a sheet, read from the audit file as it holds them, newest first. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/audit")
@Validated
public class AuditController {

    private final AuditService audit;

    public AuditController(AuditService audit) {
        this.audit = audit;
    }

    /** Every line of the sheet, or (with a name) only those about that person,
     * then those about them on its descendants (sheets by id), then those about them from the sheet they
     * were transferred from. */
    @GetMapping
    public List<String> lines(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestParam(defaultValue = "") @Size(max = 200) String name) {
        return audit.lines(sheetId.trim(), name);
    }
}
package net.officefloor.hq.app.audit;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The audit lines a sheet's viewer shows, read from the audit file as it holds them. */
@Service
public class AuditService {

    private final Audit audit;
    private final PersonRepository people;
    private final SheetRepository sheets;

    public AuditService(Audit audit, PersonRepository people, SheetRepository sheets) {
        this.audit = audit;
        this.people = people;
        this.sheets = sheets;
    }

    /**
     * The sheet's lines, newest first, or (with a name) only those about that person, followed by the
     * lines about them on each of the sheet's descendants (sheets by id, each newest first); when the
     * person so named on the sheet was transferred to it, followed by the lines about them from the
     * sheet they came from, newest first, as that sheet's lines hold them.
     */
    @Transactional(readOnly = true)
    public List<String> lines(String sheetId, String name) {
        List<String> lines = new ArrayList<>(audit.lines(sheetId, name));
        if (name != null && !name.isBlank()) {
            for (String descendant : descendantsOf(sheetId)) {
                lines.addAll(audit.lines(descendant, name));
            }
            people.findBySheetIdAndNameKey(sheetId, Person.keyOf(name))
                    .map(Person::getOriginSheetId)
                    .ifPresent(origin -> lines.addAll(audit.lines(origin, name)));
        }
        return lines;
    }

    /** The ids of the sheet's children, their children, and so on, in id order. */
    private Set<String> descendantsOf(String sheetId) {
        Set<String> found = new TreeSet<>();
        Deque<String> parents = new ArrayDeque<>();
        parents.add(sheetId);
        while (!parents.isEmpty()) {
            for (Sheet child : sheets.findByParentIdOrderByIdAsc(parents.poll())) {
                if (!child.getId().equals(sheetId) && found.add(child.getId())) parents.add(child.getId());
            }
        }
        return found;
    }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

// The audit lines of a sheet, read from the server as the audit file holds them, newest first.
@Injectable({ providedIn: 'root' })
export class AuditService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The sheet's audit lines; with a name (not blank), only those about that person. */
  lines(sheet: string, name: string): Promise<string[]> {
    return firstValueFrom(
      this.http.get<string[]>(`/api/sheets/${encodeURIComponent(sheet)}/audit`, {
        params: { name },
        headers: this.session.headers(),
      }),
    );
  }
}
import { Component, effect, inject, signal } from '@angular/core';
import { Session } from '../../core/session';
import { AuditService } from './audit.service';
import { FigurePipe } from '../../core/figure.pipe';

// The audit viewer: the sheet's audit lines exactly as the audit file holds them, newest first, or with
// a name in the filter only the lines about that person (name= or person= that name, case and
// surrounding spaces ignored). It reads the file; it records nothing.
@Component({
  selector: 'app-audit',
  imports: [FigurePipe],
  template: `
    <section aria-labelledby="audit-heading">
      <h2 id="audit-heading">Audit</h2>
      <form (submit)="show($event)" aria-label="Audit filter">
        <label for="audit-filter">Person</label>
        <input id="audit-filter" data-testid="audit-filter" [value]="filter()" (input)="filter.set(value($event)); error.set(null)" />
        <button type="submit" data-testid="audit-show">Show audit</button>
        @if (error(); as message) {
          <p role="alert" class="error" data-testid="audit-error">{{ (message) | figure }}</p>
        }
      </form>
      @if (lines().length > 0) {
        <ol data-testid="audit-list">
          @for (line of lines(); track $index) {
            <li data-testid="audit-line">{{ (line) | figure }}</li>
          }
        </ol>
      }
    </section>
  `,
  styles: `
    form {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
      align-items: center;
      margin-bottom: 0.5rem;
    }
    ol {
      list-style: none;
      padding: 0;
      font-family: monospace;
      overflow-wrap: anywhere;
    }
    .error {
      color: #a40000;
      margin: 0;
    }
  `,
})
export class Audit {
  private readonly session = inject(Session);
  private readonly service = inject(AuditService);

  protected readonly filter = signal('');
  protected readonly lines = signal<string[]>([]);
  protected readonly error = signal<string | null>(null);
  private asked = 0;

  constructor() {
    effect(() => {
      this.session.sheetId();
      this.session.loads();
      this.asked++;
      this.filter.set('');
      this.lines.set([]);
      this.error.set(null);
    });
  }

  protected value(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

  protected async show(event: Event): Promise<void> {
    event.preventDefault();
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const ask = ++this.asked;
    this.lines.set([]);
    this.error.set(null);
    try {
      const lines = await this.service.lines(sheet, this.filter());
      if (ask === this.asked) this.lines.set(lines);
    } catch {
      if (ask === this.asked) this.error.set('The audit could not be read.');
    }
  }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.settings.DelegationService;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    /** The lines that only report figures: they never say whom a change was made for. */
    private static final Set<String> FIGURES = Set.of("ROLLUP", "TOTALS", "ALERT");

    private final Path file;
    private final ObjectProvider<DelegationService> delegations;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, ObjectProvider<DelegationService> delegations) {
        this.file = Path.of(path);
        this.delegations = delegations;
